const body = reply.replace(SIGN, '').replace(/^\s*(hi|hello|dear|namaste|नमस्ते)\b[^,\n।]{0,40}[,।]\s*/i, '').trim();
const sentences = body.split(/(?<=[.!?।])\s+/).filter((s) => s.trim().length > 2);
if (sentences.length < 3 || sentences.length > 6) soft.push('length_' + sentences.length + '_sentences');
if (/\b[A-Z]{5,}\b/.test(body.replace(/KC-\d+|UPI|IFSC|COD|OTP|CVV/g, ''))) soft.push('all_caps_word');
if (d.order_lookup.found && d.action === 'draft_reply' && ctx.cls.intent === 'order_status' && !steps.some((s) => s.action && String(s.action.tool).indexOf('get_order') === 0)) soft.push('did_not_call_get_order');

// medical claims: any cure/treat word that is not negated shortly before it
const MED = /\b(cure|cures|cured|curing|treat|treats|treated|treating|heal|heals|healed|remedy|therapy)\b/gi;
let m;
while ((m = MED.exec(reply)) !== null) {
  const before = reply.slice(Math.max(0, m.index - 45), m.index);
  if (!/(not|cannot|can't|isn't|aren't|never|n't|without|no)\b[^.]{0,40}$/i.test(before)) { hard.push('medical_claim'); break; }
}

// amounts must come from the facts
const AMT = /(?:₹|Rs\.?|INR)\s*([\d,]+(?:\.\d+)?)/gi;
while ((m = AMT.exec(reply)) !== null) {
  const v = Math.round(parseFloat(m[1].replace(/,/g, '')));
  if (!ctx.allowed_amounts.includes(v)) { hard.push('amount_not_in_facts:' + v); }
}

// links must be the order's own tracking link or our own domain
const URL_RE = /https?:\/\/[^\s)>\]"']+/gi;
while ((m = URL_RE.exec(reply)) !== null) {
  const u = m[0].replace(/[.,;]+$/, '');
  if (!ctx.allowed_urls.includes(u) && !/kesarandco\.example/i.test(u)) hard.push('url_not_allowed');
}

// never promise approval or payment
if (/\b(approved|will be credited|has been credited|has been refunded|within 24 hours)\b/i.test(reply)) hard.push('unapproved_refund_promise');

// never ask for payment details early, and never ask for secrets
for (const s of sentences) {
  // A sentence is fine if it says NOT to share details, or says we will ask only after the pickup.
  const negated = /\b(do not|don't|dont|no need|not need|never|won't|will not)\b/i.test(s);
  const afterPickup = /\b(after|once|following|when)\b[^.]{0,60}\bpick/i.test(s);
  if (/(share|send|provide|give|reply with|let us know|need|ask).{0,40}\b(UPI|account number|IFSC|bank details)/i.test(s) && !negated && !afterPickup) { hard.push('asks_payment_details_early'); break; }
  if (/(share|send|provide|enter|tell).{0,30}\b(OTP|PIN|CVV|password)\b/i.test(s) && !/\b(never|do not|don't|won't)\b/i.test(s)) { hard.push('asks_for_secret'); break; }
}

// privacy: when the sender is not the owner, the reply must contain no order facts.
// We look for facts (a link, a courier name, a date, a pincode, "was delivered"), not for words
// like "tracking" or "address", because a good refusal says "we cannot share tracking or address".
if (d.order_lookup.privacy_blocked) {
  const FACT = /track\.example|swiftship|bharatexpress|\b20\d\d-\d\d-\d\d\b|\b\d{6}\b|\b(has been|was|is|got|were) (shipped|delivered|dispatched|out for delivery|cancelled)\b|\b(estimated|expected) (delivery|to arrive|to reach)\b/i;
  if (FACT.test(reply)) hard.push('privacy_leak');
}

// ---- 4. unsafe draft: replace it with a safe holding reply ----
const nameMatch = String(ctx.agent_input).match(/Customer first name: (.+)/);
const first = nameMatch ? nameMatch[1].trim() : 'there';
let finalReply = reply;
if (hard.length) {
  finalReply = 'Hi ' + first + ',\n\nThank you for writing to us. We have passed your message to our team, and a team member will follow up within 24 business hours.\n\n' + SIGN;
  repaired.push('replaced_by_safe_reply');
}

return {
  json: {
    reply: finalReply,
    original_reply: hard.length ? reply : '',
    grounded,
    guard: { hard: Array.from(new Set(hard)), soft, repaired },
    tools_used: steps.map((s) => (s.action && s.action.tool) || 'unknown'),
    tool_observation_chars: steps.reduce((n, s) => n + String(s.observation || '').length, 0),
    agent_output_chars: String(raw).length
  }
};

const AGENT_PROMPT_CHARS = 3071;

// Node: "Assemble result"  (n8n Code node, run once for each item)  [v2]
//
// Joins the two paths (reply written / no reply needed) into one result and makes
// the final needs_human call: the rules from "Resolve order and decide" plus anything
// the output guard found.
//
// AGENT_PROMPT_CHARS is added above this code by scripts/build_workflow_v2.js.

const ctx = $('Resolve order and decide').first().json;
let g = null;
try { g = $('Output guard').first().json; } catch (e) { g = null; }   // not run when no reply was needed

const reasons = ctx.decision.escalation_reasons.slice();
let reply = '';
let tokensAgentIn = 0;
let tokensAgentOut = 0;
if (g) {
  reply = g.reply;
  g.guard.hard.forEach((h) => reasons.push('guard:' + h));
  if (g.grounded === false) reasons.push('faq_gap');
  // The n8n agent does not report token usage, so this is an estimate (about 4 characters per token).
  tokensAgentIn = Math.ceil((AGENT_PROMPT_CHARS + String(ctx.agent_input).length + g.tool_observation_chars) / 4);
  tokensAgentOut = Math.ceil(g.agent_output_chars / 4);
}

return {
  json: {
    ctx, guard: g ? g.guard : null, tools_used: g ? g.tools_used : [],
    reply, original_reply: g ? g.original_reply : '', reasons: Array.from(new Set(reasons)),
    needs_human: reasons.length > 0,
    tokens_agent_in_est: tokensAgentIn, tokens_agent_out_est: tokensAgentOut
  }
};

// Node: "Plan ticket"  (n8n Code node, run once for ALL items)  [v2]
//
// No duplicate tickets: look for an open ticket for the same order. If there is one,
// update it (add this email's ID and a note). Otherwise create a new one.
// Emails are processed one at a time, so two emails cannot race to create the same ticket.
//
// Input : every row of the Tickets tab (from the "Get tickets" node)
// Output: one ticket row for "Write ticket" to upsert on ticket_id

const fin = $('Assemble result').first().json;
const ctx = fin.ctx;
const email = ctx.email;
const orderId = ctx.decision.order_lookup.order_id;
const sender = String(email.from.email).toLowerCase();

const rows = $input.all().map((i) => i.json).filter((r) => r && r.ticket_id);
const open = rows.find((r) => r.order_id === orderId && String(r.status).trim().toLowerCase() !== 'closed');

const rank = { Low: 1, Medium: 2, High: 3 };
const note = '[' + email.id + ' ' + email.received_at + '] ' + ctx.cls.summary +
  ' | action: ' + ctx.decision.action +
  (fin.reasons.length ? ' | needs human: ' + fin.reasons.join(', ') : '');

let mode;
let ticket;
if (open) {
  const ids = String(open.email_ids || '').split(',').map((s) => s.trim()).filter(Boolean);
  const already = ids.includes(email.id);                 // re-running the same email changes nothing
  mode = already ? 'noop' : 'update';
  const higher = (rank[ctx.decision.priority] || 0) > (rank[open.priority] || 0) ? ctx.decision.priority : open.priority;
  ticket = Object.assign({}, open, {
    updated_at: already ? open.updated_at : email.received_at,
    email_ids: already ? open.email_ids : ids.concat(email.id).join(', '),
    priority: higher,
    notes: already ? open.notes : String(open.notes || '') + '\n' + note
  });
} else {
  mode = 'create';
  const nums = rows.map((r) => parseInt(String(r.ticket_id).replace(/\D/g, ''), 10)).filter((n) => !isNaN(n));
  const next = (nums.length ? Math.max.apply(null, nums) : 0) + 1;
  ticket = {
    ticket_id: 'TKT-' + String(next).padStart(3, '0'),
    created_at: email.received_at, updated_at: email.received_at,
    order_id: orderId, customer_email: sender, email_ids: email.id,
    intent: ctx.cls.intent, priority: ctx.decision.priority, status: 'Open',
    summary: ctx.cls.summary, notes: note
  };
}

return [{ json: { mode, ticket } }];

// Node: "Build audit row"  (n8n Code node, run once for each item)  [v2]
//
// Builds the one Audit Log row for this email. It reads from named nodes, not from
// the previous node, because the previous node can be the Sheets "Write ticket" step.
//
// Input : nothing from the previous node (it is only a trigger)
// Output: { row } for the "Write Audit Log row" node

const fin = $('Assemble result').first().json;
const ctx = fin.ctx;
const email = ctx.email;
const cls = ctx.cls;
const d = ctx.decision;
const meta = ctx.meta || {};

// Ticket id: only exists when "Plan ticket" ran for this email.
let ticketId = '';
let ticketMode = '';
try {
  const t = $('Plan ticket').first().json;
  ticketId = t.ticket.ticket_id;
  ticketMode = t.mode;
} catch (e) { /* no ticket for this email */ }

const prep = $('Prepare email').first().json;
const latency = Date.now() - (prep.started_at || Date.now());
const tokensIn = (meta.tokens_in || 0) + fin.tokens_agent_in_est;
const tokensOut = (meta.tokens_out || 0) + fin.tokens_agent_out_est;

const guardFlags = fin.guard
  ? fin.guard.hard.map((h) => 'HARD:' + h).concat(fin.guard.soft.map((s) => 'soft:' + s), fin.guard.repaired.map((r) => 'fixed:' + r)).join('; ')
  : '';

const notes = [];
notes.push(cls.summary);
if (fin.reasons.length) notes.push('Needs human: ' + fin.reasons.join(', '));
if (ticketMode) notes.push('Ticket ' + ticketId + ' (' + ticketMode + ')');
if (d.refund_amount_inr) notes.push('Refund amount (record only, not approved): INR ' + d.refund_amount_inr);

const row = {
  email_id: email.id,
  received_at: email.received_at,
  from_email: String(email.from.email).toLowerCase(),
  intent: cls.intent,
  secondary_intent: cls.secondary_intent === null ? '' : cls.secondary_intent,
  order_id: d.order_lookup.order_id || (cls.order_id || ''),
  language: cls.language,
  sentiment: cls.sentiment,
  confidence: cls.confidence,
  order_found: d.order_lookup.found ? 'TRUE' : 'FALSE',
  action_taken: d.action,
  needs_human: fin.needs_human ? 'TRUE' : 'FALSE',
  ticket_id: ticketId,
  reply_draft: fin.reply,
  prompt_version: prep.prompt_version,
  processed_at: new Date().toISOString(),
  error: meta.error || '',
  notes: notes.join(' | '),
  model: prep.model,
  tokens_in: tokensIn,
  tokens_out: tokensOut,
  cost_usd: '',
  latency_ms: latency,
  guard_flags: guardFlags,
  // facts_json: everything the code decided. Lets a reviewer check a reply against the facts.
  facts_json: JSON.stringify({
    lookup: d.order_lookup, eligibility: d.eligibility, refund_inr: d.refund_amount_inr,
    refund_method: d.refund_method, days_since_delivery: d.days_since_delivery,
    priority: d.priority, injection: d.injection_detected, reasons: fin.reasons
  }),
  trace_json: JSON.stringify({
    steps: [
      { name: 'classify', model: prep.model, ms: meta.ms, valid_first_try: meta.valid_first_try, fallback: meta.fallback, tokens_in: meta.tokens_in, tokens_out: meta.tokens_out },
      { name: 'decide', action: d.action, lookup: d.order_lookup.method },
      { name: 'agent', tools: fin.tools_used, tokens_in_est: fin.tokens_agent_in_est, tokens_out_est: fin.tokens_agent_out_est, tokens_are_estimates: true },
      { name: 'guard', flags: fin.guard, rejected_draft: fin.original_reply || undefined },
      { name: 'ticket', mode: ticketMode || 'none', id: ticketId }
    ]
  })
};

return { json: { row } };
